def largest_prime_factor(n: int) -> int:
    if n <= 1:
        return n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i
    return n

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    if last == 1:
        memo[last] = 1
        return 1

    count = 1  # The sequence ending with 'last' itself is valid
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

