def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # dp[j] will be True if we can achieve volume j
    from typing import List
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in volumes:
        # Traverse from V down to vol to avoid using the same item multiple times
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True

    # Find the maximum volume that can be achieved
    max_occupied = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_occupied = j
            break

    return V - max_occupied

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.lower()
    key_index = 0
    plaintext = []

    for char in ciphertext:
        if char.isalpha():
            key_char = key[key_index % len(key)]
            key_index += 1

            if char.isupper():
                base = ord('A')
            else:
                base = ord('a')

            # For decryption, we subtract the key shift
            shift = ord(key_char) - ord('a')
            decrypted_char = chr((ord(char) - base - shift) % 26 + base)
            plaintext.append(decrypted_char)
        else:
            plaintext.append(char)

    return ''.join(plaintext)

